"""Paired reaction descriptions and backup jokes; normal wording may be episode-specific."""
from __future__ import annotations
import json
from pathlib import Path

JOKES = json.loads(r'''{"high-five":["Like and subscribe. Virtual high five. Zero awkward eye contact.","Like and subscribe. That high five costs less than another terrible sequel.","Hit like and subscribe. I'll handle both sides of the high five.","Like and subscribe. Finally, a high five nobody can leave hanging.","Like and subscribe. The other hand has already agreed.","Like and subscribe. My hand has been waiting for this moment."],"logical-cat":["Like and subscribe. It's only logical. Even the cat agrees.","Like and subscribe. Excellent movie taste is logical. Petting the cat is optional.","Like and subscribe. The cat reviewed the evidence. Apparently I'm worth keeping.","Like and subscribe. Even space cats need something good to watch.","Like and subscribe. A perfectly logical decision with absolutely no paperwork.","Like and subscribe. The cat accepts clicks. I accept emotional support."],"crying-cat":["Like and subscribe. This cat believes in my movie career. Please don't tell him.","Like and subscribe. My mom thinks I'm unemployed. The cat is starting to agree.","Like and subscribe. The cat says he's fine. My subscriber count says otherwise.","Like and subscribe. This is the face of someone refreshing YouTube Studio.","Like and subscribe. I'm handling rejection about as well as this cat.","Like and subscribe. We're one click away from pretending everything is fine."],"hiding":["Like and subscribe. Me disappearing after recommending one bad movie.","Like and subscribe. My social skills end immediately after this sentence.","Like and subscribe. Then we can both pretend this wasn't awkward.","Like and subscribe. I'll just quietly disappear while you find the button.","Like and subscribe. Before I retreat into the bushes of unemployment.","Like and subscribe. Asking for support has clearly gone very smoothly."],"facepalm":["Like and subscribe. Save me from making this face at my analytics.","Like and subscribe. Even the captain can't explain my upload schedule.","Like and subscribe. My backup plan has already received this reaction.","Like and subscribe. That's my face after another unnecessary sequel.","Like and subscribe. My career choices are under a very thorough review.","Like and subscribe. Please give the captain one less thing to worry about."],"approval":["Like and subscribe. Keanu brought the thumbs up. You bring the click.","Like and subscribe. The approval department has finished its investigation.","Like and subscribe. A tiny click. A completely unreasonable amount of happiness.","Like and subscribe. Consider this your official permission to enjoy better movies.","Like and subscribe. Finally, a recommendation with a thumbs up attached.","Like and subscribe. That's the entire approval process. Beautifully inefficient."],"dramatic-dog":["Like and subscribe. That dog just saw my subscriber count.","Like and subscribe. The dramatic zoom was clearly necessary.","Like and subscribe. My reaction when someone actually follows my recommendations.","Like and subscribe. Even the dog wasn't ready for that plot twist.","Like and subscribe. This is how seriously I take movie night.","Like and subscribe. Please act surprised when this channel becomes successful."],"mic-drop":["Like and subscribe. That was the speech. Budget permitting, we'll replace the microphone.","Like and subscribe. Strong exit. Terrible microphone insurance.","Like and subscribe. My entire argument has now hit the floor.","Like and subscribe. I'd explain further, but the microphone has resigned.","Like and subscribe. An unnecessarily dramatic ending to a very small request.","Like and subscribe. The microphone gave everything for this announcement."],"celebration":["Like and subscribe. This is my completely normal reaction to one new subscriber.","Like and subscribe. My entire marketing budget went into this dance.","Like and subscribe. Excellent taste. Questionable dance moves.","Like and subscribe. Celebrate responsibly. Preferably with better dancing than this.","Like and subscribe. Your watchlist is growing. Apparently so is my confidence.","Like and subscribe. I promise the movie recommendations are better than the choreography."]}''')
DESCRIPTIONS = json.loads(r'''{"high-five":"A person gives herself a high five; friendly awkward self encouragement.","logical-cat":"Spock strokes a cat calmly; dry logic, quiet confidence and movie nerd humor.","crying-cat":"A crying cat gives a thumbs up; mock sadness and gentle self-deprecation.","hiding":"Homer Simpson slowly backs into a hedge; awkward retreat and embarrassment.","facepalm":"Captain Picard covers his face; disbelief, frustration and dry self-deprecation.","approval":"Keanu Reeves gives a thumbs up; warm approval and friendly encouragement.","dramatic-dog":"A pug reacts with an intense dramatic look; surprise and overreaction.","mic-drop":"Bryan Cranston drops a microphone; a brief confident, theatrical exit.","celebration":"Carlton dances enthusiastically; celebration, joy and awkward confidence."}''')
EXTRA_STYLES = json.loads(r'''{"homer-disappear-bush.gif.b64":{"theme":"hiding","headline":"NO PRESSURE."},"picard-facepalm.gif.b64":{"theme":"facepalm","headline":"HELP THE CAPTAIN."},"keanu-thumbs-up.gif.b64":{"theme":"approval","headline":"APPROVED."},"dramatic-pug.gif.b64":{"theme":"dramatic-dog","headline":"THAT REACTION."},"mic-drop-bryan-cranston.gif.b64":{"theme":"mic-drop","headline":"THAT'S THE SPEECH."},"dancing-carlton.gif.b64":{"theme":"celebration","headline":"TINY VICTORY."}}''')


def expand_reactions(existing):
    rows = []
    for reaction in existing:
        theme = reaction["theme"]
        rows.append({**reaction, "description": DESCRIPTIONS[theme], "jokes": tuple(JOKES[theme])})
    manifest = Path(__file__).resolve().parents[1]/"assets"/"memes"/"extra-reactions.json"
    try:
        additions = json.loads(manifest.read_text())
    except (OSError, ValueError):
        additions = []
    for item in additions:
        style = EXTRA_STYLES.get(item.get("asset"))
        if not style:
            continue
        theme = style["theme"]
        rows.append({**item, **style, "animated": True,
                     "description": DESCRIPTIONS[theme], "jokes": tuple(JOKES[theme])})
    return tuple(rows)
